CONTROL_ROOM_TEST_BLOCK_AGENT_CLI=1 node --import tsx --input-type=module -e 'import test from "node:test";
import assert from "node:assert/strict";
import fs from "node:fs";
import {mkdtemp,realpath,rm,mkdir} from "node:fs/promises";
import {tmpdir} from "node:os";
import {join} from "node:path";
import {syncBuiltinESMExports} from "node:module";
import {execFileSync} from "node:child_process";
import {Client} from "pg";
import {randomBytes} from "node:crypto";
import {withRealPostgres} from "./tests/support/attack-kit/real-postgres.ts";
import {runMacDatabaseUpgradeVpsStepV1} from "./scripts/mac-local/database-upgrade-vps-step.mjs";
import {databaseRoleManifestV1} from "./scripts/mac-local/database-role-manifest.mjs";
import {postgresScramVerifierV1} from "./scripts/mac-local/database-upgrade-scram.mjs";
test("VPS reservation owner closes descriptors after success and backup failure",{timeout:600000},async()=>{
 const root=await mkdtemp(join(await realpath(tmpdir()),"vps-reservation-probe-"));
 try {
  const result=await withRealPostgres(async pg=>{
   const client=new Client(pg.admin());await client.connect();
   try {await client.query("CREATE ROLE postgres SUPERUSER LOGIN");await client.query("DROP SCHEMA control_room_queue CASCADE");}finally{await client.end();}
   const target="host="+pg.host+" port="+pg.port+" dbname="+pg.database+" user=postgres";
   const commit=execFileSync("git",["rev-parse","refs/remotes/origin/main"],{encoding:"utf8"}).trim();
   const handles=[],original=fs.promises.open;
   fs.promises.open=async(...args)=>{
    const h=await original(...args);
    if((await h.stat()).isDirectory()&&String(args[0]).startsWith(root))handles.push(h);
    return h;
   };syncBuiltinESMExports();
   try {
    for(const failure of [true,false]){
     const backupRoot=join(root,failure?"failed":"success");await mkdir(backupRoot,{mode:0o700});
     const args=["plan",commit,target,backupRoot,process.env.PG_BIN,"1"];
     const plan=await runMacDatabaseUpgradeVpsStepV1({args,write:()=>{}});
     const codes=JSON.stringify(Object.fromEntries(plan.plan.createRoles
      .filter(r=>Object.hasOwn(databaseRoleManifestV1.logins,r.role))
      .map(r=>[r.role,postgresScramVerifierV1(randomBytes(32).toString("base64url"))])));
     args[0]="apply";args[4]=failure?join(root,"missing-bin"):process.env.PG_BIN;args.push(plan.digest);
     if(failure)await assert.rejects(runMacDatabaseUpgradeVpsStepV1({args,write:()=>{},readCode:async()=>codes}),/upgrade_backup_failed/);
     else await assert.doesNotReject(runMacDatabaseUpgradeVpsStepV1({args,write:()=>{},readCode:async()=>codes}),
       "real VPS apply must finish before descriptor cleanup is inspected");
     assert.equal(handles.length,failure?1:2,"each VPS path reaches its real reservation");
     for(const h of handles)await assert.rejects(h.stat(),{code:"EBADF"},"VPS owner must release every reserved descriptor");
    }
   }finally{fs.promises.open=original;syncBuiltinESMExports();await Promise.all(handles.map(h=>h.close()));}
  },{port:60871,allowedPorts:[60871],pgBin:process.env.PG_BIN,boundMs:540000});
  assert.equal(result.cleanedUp,true);assert.deepEqual(result.leftovers,[]);
 }finally{await rm(root,{recursive:true,force:true});}
});'
